:root {
  --bg: #1e1e2e;
  --card-bg: #2a2a3c;
  --primary: #a6e3a1;
  --accent: #f38ba8;
  --text: #cdd6f4;
  --muted: #6c7086;
  --border: #45475a;
  --focus: #89b4fa;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.game-card {
  background: var(--card-bg);
  border-radius: 16px;
  padding: 24px;
  width: 100%;
  max-width: 480px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

header {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 8px;
}

h1 {
  font-size: 1.5rem;
  color: var(--primary);
  letter-spacing: 0.5px;
}

.score {
  font-size: 1.1rem;
  font-weight: 600;
}

.score span {
  color: var(--accent);
}

.board-wrapper {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1;
  border-radius: 8px;
  overflow: hidden;
  border: 2px solid var(--border);
  background: #11111b;
}

canvas {
  display: block;
  width: 100%;
  height: 100%;
  image-rendering: pixelated;
}

.overlay {
  position: absolute;
  inset: 0;
  background: rgba(17, 17, 27, 0.92);
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 20px;
  transition: opacity 0.2s ease;
}

.overlay.hidden {
  opacity: 0;
  pointer-events: none;
}

.overlay-content {
  display: flex;
  flex-direction: column;
  gap: 16px;
  align-items: center;
  max-width: 320px;
}

.overlay-content h2 {
  font-size: 1.4rem;
  color: var(--primary);
}

.overlay-content p {
  line-height: 1.5;
  color: var(--text);
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

button {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  padding: 12px 24px;
  border-radius: 8px;
  border: 2px solid transparent;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s, border-color 0.15s;
  min-width: 120px;
}

button:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

button.primary {
  background: var(--primary);
  color: #1e1e2e;
}

button.primary:hover {
  background: #b9f0b4;
}

button.primary:active {
  transform: scale(0.97);
}

button.secondary {
  background: transparent;
  border-color: var(--border);
  color: var(--text);
}

button.secondary:hover:not(:disabled) {
  background: var(--border);
}

button.secondary:active:not(:disabled) {
  transform: scale(0.97);
}

button:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.hint {
  text-align: center;
  font-size: 0.9rem;
  color: var(--muted);
}

@media (max-width: 400px) {
  .game-card {
    padding: 16px;
  }
  button {
    min-width: 100px;
    padding: 10px 16px;
  }
}

(function () {
  'use strict';

  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const scoreEl = document.getElementById('score');
  const overlay = document.getElementById('overlay');
  const overlayTitle = document.getElementById('overlay-title');
  const overlayText = document.getElementById('overlay-text');
  const startBtn = document.getElementById('start-btn');
  const pauseBtn = document.getElementById('pause-btn');
  const restartBtn = document.getElementById('restart-btn');

  const GRID = 20;
  const CELL = canvas.width / GRID;
  const TICK_MS = 120;

  const COLORS = {
    snake: '#a6e3a1',
    snakeHead: '#b9f0b4',
    food: '#f38ba8',
    grid: '#1e1e2e'
  };

  let snake, dir, nextDir, food, score, running, paused, gameOver, loopId;

  function reset() {
    snake = [{ x: 10, y: 10 }];
    dir = { x: 1, y: 0 };
    nextDir = { x: 1, y: 0 };
    score = 0;
    gameOver = false;
    paused = true;
    running = false;
    scoreEl.textContent = '0';
    placeFood();
    clearInterval(loopId);
    loopId = null;
    pauseBtn.disabled = true;
    pauseBtn.textContent = 'Pause';
    draw();
  }

  function placeFood() {
    let pos;
    do {
      pos = { x: Math.floor(Math.random() * GRID), y: Math.floor(Math.random() * GRID) };
    } while (snake.some(s => s.x === pos.x && s.y === pos.y));
    food = pos;
  }

  function startGame() {
    reset();
    running = true;
    paused = false;
    pauseBtn.disabled = false;
    overlay.classList.add('hidden');
    startLoop();
  }

  function startLoop() {
    clearInterval(loopId);
    loopId = setInterval(tick, TICK_MS);
  }

  function tick() {
    if (!running || paused || gameOver) return;

    dir = nextDir;
    const head = { x: snake[0].x + dir.x, y: snake[0].y + dir.y };

    if (head.x < 0 || head.x >= GRID || head.y < 0 || head.y >= GRID) {
      return endGame();
    }
    if (snake.some(s => s.x === head.x && s.y === head.y)) {
      return endGame();
    }

    snake.unshift(head);

    if (head.x === food.x && head.y === food.y) {
      score += 10;
      scoreEl.textContent = String(score);
      placeFood();
    } else {
      snake.pop();
    }

    draw();
  }

  function endGame() {
    gameOver = true;
    running = false;
    clearInterval(loopId);
    pauseBtn.disabled = true;
    overlayTitle.textContent = 'Game Over';
    overlayText.textContent = 'Final score: ' + score + '. Try again?';
    startBtn.textContent = 'Play Again';
    overlay.classList.remove('hidden');
  }

  function togglePause() {
    if (!running || gameOver) return;
    paused = !paused;
    pauseBtn.textContent = paused ? 'Resume' : 'Pause';
    if (paused) {
      overlayTitle.textContent = 'Paused';
      overlayText.textContent = 'Press Space or click Resume to continue.';
      startBtn.textContent = 'Resume';
      overlay.classList.remove('hidden');
    } else {
      overlay.classList.add('hidden');
    }
  }

  function draw() {
    ctx.fillStyle = COLORS.grid;
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.fillStyle = COLORS.food;
    ctx.fillRect(food.x * CELL, food.y * CELL, CELL, CELL);

    snake.forEach((seg, i) => {
      ctx.fillStyle = i === 0 ? COLORS.snakeHead : COLORS.snake;
      ctx.fillRect(seg.x * CELL + 1, seg.y * CELL + 1, CELL - 2, CELL - 2);
    });
  }

  function handleKey(e) {
    const key = e.key;
    if (key === ' ' || key === 'Spacebar') {
      e.preventDefault();
      if (running && !gameOver) togglePause();
      return;
    }
    if (!running || paused || gameOver) return;

    let newDir = null;
    if (key === 'ArrowUp') newDir = { x: 0, y: -1 };
    else if (key === 'ArrowDown') newDir = { x: 0, y: 1 };
    else if (key === 'ArrowLeft') newDir = { x: -1, y: 0 };
    else if (key === 'ArrowRight') newDir = { x: 1, y: 0 };

    if (newDir) {
      e.preventDefault();
      if (newDir.x !== -dir.x || newDir.y !== -dir.y) {
        nextDir = newDir;
      }
    }
  }

  startBtn.addEventListener('click', () => {
    if (running && paused && !gameOver) {
      togglePause();
    } else {
      startGame();
    }
  });

  pauseBtn.addEventListener('click', togglePause);

  restartBtn.addEventListener('click', () => {
    reset();
    overlayTitle.textContent = 'How to Play';
    overlayText.textContent = 'Use arrow keys to move. Eat the red food to grow and score. Don\'t hit the walls or yourself!';
    startBtn.textContent = 'Start Game';
    overlay.classList.remove('hidden');
  });

  document.addEventListener('keydown', handleKey);

  reset();
})();
